#!/usr/bin/env node
// Writes fixtures.ts: each input of inputs.mjs compressed by Node's zlib in
// the ways a server meets — every gzip level, the four strategies, small
// windows, flushes between pieces, two members — and a handful of known-bad
// streams, each with the error `main.ts` must answer and that Node also
// refuses (tests/run.js checks Node's half). Run it again after a change to
// inputs.mjs; the output depends on Node's bundled zlib, so it is committed,
// not regenerated by the suite.
import fs from "node:fs"
import zlib from "node:zlib"
import { INPUTS } from "./inputs.mjs"

const C = zlib.constants
const good = []
const add = (name, input, format, bytes) => good.push({ name, input, format, hex: bytes.toString("hex") })
for (const [input, data] of Object.entries(INPUTS)) {
  for (const level of data.length <= 6000 ? [0, 1, 6, 9] : [1, 6, 9]) {
    add(`gzip -${level}`, input, "gzip", zlib.gzipSync(data, { level }))
  }
  add("raw -6", input, "raw", zlib.deflateRawSync(data, { level: 6 }))
  add("zlib -6", input, "zlib", zlib.deflateSync(data, { level: 6 }))
}
for (const input of ["text", "json", "mixed"]) {
  const data = INPUTS[input]
  add("gzip two members", input, "gzip", Buffer.concat([zlib.gzipSync(data.subarray(0, 1000)), zlib.gzipSync(data.subarray(1000))]))
  if (input === "mixed") {
    continue
  }
  for (const [strategy, label] of [
    [C.Z_FILTERED, "filtered"],
    [C.Z_HUFFMAN_ONLY, "huffman-only"],
    [C.Z_RLE, "rle"],
    [C.Z_FIXED, "fixed"],
  ]) {
    add(`gzip ${label}`, input, "gzip", zlib.gzipSync(data, { strategy }))
  }
  add("raw windowBits 9", input, "raw", zlib.deflateRawSync(data, { windowBits: 9 }))
  add("zlib memLevel 1", input, "zlib", zlib.deflateSync(data, { memLevel: 1 }))
  // Pieces sync-flushed one after another, then an empty final block: raw
  // streams that end byte-aligned without BFINAL concatenate into one.
  const pieces = []
  for (let at = 0; at < data.length; at += 3001) {
    pieces.push(zlib.deflateRawSync(data.subarray(at, at + 3001), { finishFlush: C.Z_SYNC_FLUSH }))
  }
  pieces.push(zlib.deflateRawSync(Buffer.alloc(0)))
  add("raw sync-flushed pieces", input, "raw", Buffer.concat(pieces))
}

// Known-bad streams, each refused by Node too.
const bad = []
const addBad = (name, format, bytes, code) => bad.push({ name, format, hex: bytes.toString("hex"), code })
const gz = zlib.gzipSync(INPUTS.json, { level: 6 })
const crc = Buffer.from(gz)
crc[crc.length - 8] ^= 1
addBad("gzip with a wrong CRC-32", "gzip", crc, "GZIP_ERR_CRC")
const size = Buffer.from(gz)
size[size.length - 4] ^= 1
addBad("gzip with a wrong length", "gzip", size, "GZIP_ERR_SIZE")
addBad("gzip cut in the stream", "gzip", gz.subarray(0, gz.length >> 1), "DEFLATE_ERR_TRUNCATED")
addBad("gzip cut in the trailer", "gzip", gz.subarray(0, gz.length - 3), "DEFLATE_ERR_TRUNCATED")
addBad("gzip cut in the header", "gzip", gz.subarray(0, 6), "DEFLATE_ERR_TRUNCATED")
const magic = Buffer.from(gz)
magic[0] = 0x1e
addBad("gzip with the wrong magic", "gzip", magic, "GZIP_ERR_HEADER")
const zl = zlib.deflateSync(INPUTS.text)
const adler = Buffer.from(zl)
adler[adler.length - 1] ^= 1
addBad("zlib with a wrong Adler-32", "zlib", adler, "ZLIB_ERR_ADLER")
// Raw streams written bit by bit (RFC 1951 §3.1.1: Huffman codes most
// significant bit first, everything else least).
const bits = (fields) => {
  const out = []
  let acc = 0
  let n = 0
  for (const [value, count, huffman] of fields) {
    for (let i = 0; i < count; i++) {
      const bit = huffman ? (value >> (count - 1 - i)) & 1 : (value >> i) & 1
      acc |= bit << n
      n += 1
      if (n === 8) {
        out.push(acc)
        acc = 0
        n = 0
      }
    }
  }
  if (n > 0) out.push(acc)
  return Buffer.from(out)
}
addBad(
  "raw: a distance before the start",
  "raw",
  bits([[1, 1], [1, 2], [0x91, 8, true], [1, 7, true], [3, 5, true], [0, 7, true]]),
  "DEFLATE_ERR_DISTANCE"
)
addBad(
  "raw: an over-subscribed code-length code",
  "raw",
  bits([[1, 1], [2, 2], [0, 5], [0, 5], [0, 4], [1, 3], [1, 3], [1, 3], [1, 3], [0, 32], [0, 32]]),
  "DEFLATE_ERR_HUFFMAN"
)
// HLIT 257, HDIST 1, HCLEN 16; code-length lengths 18: 1, 0: 2, 2: 2 (codes
// 0, 10, 11); then 256 zeros by two 18s, length 2 for the end-of-block and 0
// for the one distance: a lone code of length 2 is incomplete.
addBad(
  "raw: an incomplete literal/length code",
  "raw",
  bits([
    [1, 1], [2, 2], [0, 5], [0, 5], [12, 4],
    [0, 3], [0, 3], [1, 3], [2, 3], [0, 3], [0, 3], [0, 3], [0, 3], [0, 3], [0, 3], [0, 3], [0, 3], [0, 3], [0, 3], [0, 3], [2, 3],
    [0, 1, true], [127, 7], [0, 1, true], [107, 7], [3, 2, true], [2, 2, true], [0, 32],
  ]),
  "DEFLATE_ERR_HUFFMAN"
)
addBad("raw: block type 3", "raw", bits([[1, 1], [3, 2], [0, 16]]), "DEFLATE_ERR_BLOCK_TYPE")
addBad("raw: a stored block whose NLEN is wrong", "raw", Buffer.from([1, 3, 0, 0xfc, 0xfe, 1, 2, 3]), "DEFLATE_ERR_STORED_LENGTH")

const line = (fields) => `  ${fields.join(", ")},`
const ts = [
  "// Written by fixtures.mjs from Node's zlib: do not edit. Each good stream",
  "// decompresses to the input of inputs.mjs (and main.ts's `inputOf`) named",
  "// beside it; each bad one must answer the code named beside it.",
  "",
  "/** The streams Node wrote: a description, the input's name, the format, the bytes as hex. */",
  "export const goodStreams = (): string[] => [",
  ...good.map((g) => line([JSON.stringify(g.name), JSON.stringify(g.input), JSON.stringify(g.format), JSON.stringify(g.hex)])),
  "]",
  "",
  "/** Malformed streams Node refuses: a description, the format, the bytes as hex, the error's name. */",
  "export const badStreams = (): string[] => [",
  ...bad.map((b) => line([JSON.stringify(b.name), JSON.stringify(b.format), JSON.stringify(b.hex), JSON.stringify(b.code)])),
  "]",
  "",
]
fs.writeFileSync(new URL("fixtures.ts", import.meta.url), ts.join("\n"))
console.log(`fixtures.ts: ${good.length} good streams, ${bad.length} bad`)
